158		const restoredRaw = await executeReactBoilerplateZeroSwWitnessRun({
159			lane: 'migrated',
160			pass: 1,
161			laneRoot,
162			receiptRoot: join(stageRoot, 'semantic-restoration-receipt'),
163		});
164		const restored = restoredRaw as WitnessReactBoilerplateZeroSwRun;
165		if (witnessReactBoilerplateZeroSwBehaviorDigest(restored) !== behaviorDigest)
166			throw new Error('German heading restored browser behavior differs');
167		return {
168			failure: 'witness-semantic-assertion',
169			intendedFailure: true,
170			path: relative(laneRoot, target.path),
171			beforeSha256,
172			mutatedSha256,
173			afterRestoreSha256,
174			restoredByteIdentically: true,
175			restoredRun: 'pass',
176		};
177	}
178	
179	async function serviceWorkerMutation(): Promise<
180		WitnessReactBoilerplateZeroSwReceipt['mutations']['serviceWorker']
181	> {
182		const laneRoot = join(root, '.versionless/stage/react-boilerplate-v4-zero-sw/mutation-output');
183		if (!(await exists(join(laneRoot, 'sw.js'))))
184			throw new Error('Service-worker mutation output is absent');
185		let intendedFailure = false;
186		try {
187			await executeReactBoilerplateZeroSwWitnessRun({
188				lane: 'baseline',
189				pass: 1,
190				laneRoot,
191				receiptRoot: join(stageRoot, 'service-worker-mutation-receipt'),
192			});
193		} catch (error) {
194			const message = error instanceof Error ? error.message : String(error);
195			intendedFailure = message.includes('zero-service-worker policy assertion failed');
196		}
197		if (!intendedFailure)
198			throw new Error('Service-worker mutation did not make the runtime zero-SW guard red');
199		return {
200			failure: 'zero-service-worker-policy-assertion',
201			intendedFailure: true,
202			observedOutputFiles: ['sw.js'],
203			observedRegistrationOrWorker: true,
204		};
205	}
206	
207	async function writeFixtureReceipt(
208		runs: WitnessReactBoilerplateZeroSwRun[],
209		mutations: WitnessReactBoilerplateZeroSwReceipt['mutations'],
210	): Promise<ReactBoilerplateZeroSwReceipt> {
211		const artifactsRoot = join(fixtureEvidence, 'artifacts');
212		const journeyPath = join(artifactsRoot, 'witness-journeys.json');
213		const mutationPath = join(artifactsRoot, 'witness-mutations.json');
214		await writeFile(journeyPath, `${canonicalize(runs)}\n`, { flag: 'wx' });
215		await writeFile(mutationPath, `${canonicalize(mutations)}\n`, { flag: 'wx' });
216		const buildPath = join(artifactsRoot, 'build.json');
217		const receipt = {
218			schemaVersion: 'versionless.receipt.v1' as const,
219			runId: REACT_BOILERPLATE_ZERO_SW_RUN_ID,
220			fixture: REACT_BOILERPLATE_ZERO_SW_FIXTURE,
221			source,
222			tooling: {
223				legacyNode: '16.20.2',
224				targetNode: '24.15.0',
225				legacyBundler: 'webpack-4.30.0',
226				targetBundler: 'Vite-8.0.16',
227				witness: 'direct-linked-local-0.8.0',
228			},
229			consent: [
230				{
231					id: 'T693-local-reconciliation',
232					purpose: 'reuse already-ingested immutable fixture and local dependencies',
233					mode: 'consented' as const,
234				},
235			],
236			migration: {
237				file: 'app/app.js + internals/webpack/webpack.prod.babel.js',
238				transform: 'react-boilerplate-zero-service-worker-profile',
239				edits: 3,
240				dependency: {
241					name: 'offline-plugin',
242					from: 'executed-and-registered',
243					to: 'retained-unused-unshipped',
244					license: 'MIT',
245				},
246				lockPatch: 'none; dependency closure retained',
247			},
248			verification: {
249				result: 'pass' as const,
250				builds: 'pass' as const,
251				journeys: 'pass' as const,
252				mutation: 'pass' as const,
253				locality: {
254					mode: 'offline' as const,
255					scope: 'Versionless-spawned build processes and Playwright browser requests',
256					osWideIsolation: false as const,
257					successfulNonLoopback: 0 as const,
258					browserBlockedRequests: 0,
259				},
260				deterministicCore: {
261					first: runs[0]!.behaviorDigest,
262					second: runs[3]!.behaviorDigest,
263					equal: true as const,
264				},
265			},
266			artifacts: [buildPath, journeyPath, mutationPath].map((path) => ({
267				path: relative(root, path),
268				sha256: '',
269			})),
270			integrity: {
271				algorithm: 'sha256' as const,
272				canonicalDigest: '',
273				authenticity: 'not-established' as const,
274			},
275			limitations: [
276				'This reconciles one already-counted React lineage and does not advance official or aligned readiness before Judge audit.',
277				'The zero-service-worker profile supersedes T060 only for current policy; original offline-first evidence remains valid and retained.',
278				'Locality is process-scoped and does not establish OS-wide isolation.',
279				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
280			],
281			supersedes: {
282				scope: 'current-zero-service-worker-policy-only' as const,
283				t060: REACT_BOILERPLATE_ZERO_SW_SUPERSEDES.t060,
284				witness: REACT_BOILERPLATE_ZERO_SW_SUPERSEDES.witness,
285				originalOfflineFirstEvidenceRetained: true as const,
286				historicalZeroSwParityClaimed: false as const,
287			},
288			policyProfile: {
289				removals: [
290					'offline-plugin-runtime-registration',
291					'offline-plugin-webpack-execution',
292				] as const,
293				dependencyClosure: 'retained-unused-unshipped' as const,
294				baselineBuilds: 2 as const,
295				targetBuilds: 2 as const,
296				zeroServiceWorker: zeroObservation,
297			},
298		} satisfies ReactBoilerplateZeroSwReceipt;
299		for (const artifact of receipt.artifacts)
300			artifact.sha256 = sha256(await readFile(join(root, artifact.path)));
301		receipt.integrity.canonicalDigest = receiptDigest(receipt);
302		parseReactBoilerplateZeroSwReceipt(receipt);
303		await writeFile(fixtureReceiptPath, `${canonicalize(receipt)}\n`, { flag: 'wx' });
304		await writeFile(
305			join(fixtureEvidence, 't693-run.md'),
306			renderReactBoilerplateZeroSwReceipt(receipt),
307			{ flag: 'wx' },
308		);
309		return receipt;
310	}
311	
312	async function appendAggregate(
313		receipt: WitnessReactBoilerplateZeroSwReceipt,
314		canonicalReceipt: ReactBoilerplateZeroSwReceipt,
315	): Promise<void> {
316		const aggregate = JSON.parse(await readFile(aggregatePath, 'utf8')) as {
317			fixtures?: Array<Record<string, unknown>>;
318		};
319		if (!Array.isArray(aggregate.fixtures)) throw new Error('Corpus aggregate fixtures are absent');
320		const migrationMember = {
321			id: 'react-boilerplate-v4-zero-sw',
322			framework: 'react',
323			track: 'current-zero-service-worker-policy-reconciliation',
324			bundler: 'webpack-4.30.0-to-vite-8.0.16',
325			runtime: 'node-16.20.2-to-node-24.15.0',
326			result: 'pass',
327			receipt: 'evidence/runs/react-boilerplate-v4-zero-sw/t693-run.json',
328			digest: canonicalReceipt.integrity.canonicalDigest,
329		};
330		const member = witnessReactBoilerplateZeroSwAggregateMember(receipt.integrity.canonicalDigest);
331		const migrationIndex = aggregate.fixtures.findIndex((item) => item.id === migrationMember.id);
332		if (migrationIndex >= 0) aggregate.fixtures[migrationIndex] = migrationMember;
333		else aggregate.fixtures.push(migrationMember);
334		const index = aggregate.fixtures.findIndex((item) => item.id === member.id);
335		if (index >= 0) aggregate.fixtures[index] = member;
336		else aggregate.fixtures.push(member);
337		await writeFile(aggregatePath, `${JSON.stringify(aggregate, null, 2)}\n`);
338	}
339	
340	export async function runWitnessReactBoilerplateZeroSw(): Promise<WitnessReactBoilerplateZeroSwReceipt> {
341		if (
342			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
343			process.env.NPM_CONFIG_OFFLINE !== 'true'
344		)
345			throw new Error('React Boilerplate zero-SW Witness requires dual offline controls');
346		if (await exists(witnessEvidence))
347			throw new Error('React Boilerplate zero-SW Witness output collision');
348		await protectedHashes();
349		const provenance = await verifyLinkedWitnessProvenance(root);
350		const profile = JSON.parse(await readFile(profilePath, 'utf8')) as { result?: string };
351		if (profile.result !== 'build-profile-complete-not-promoted')
352			throw new Error('React Boilerplate zero-SW build profile is absent or differs');
353		const lanes = await stageInputs();
354		const runs = await executeRuns(lanes);
355		const mutations = {
356			semantic: await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest),
357			serviceWorker: await serviceWorkerMutation(),
358		};
359		const canonicalReceipt = await writeFixtureReceipt(runs, mutations);
360		const canonicalBytes = await readFile(fixtureReceiptPath);
361		const receipt: WitnessReactBoilerplateZeroSwReceipt = {
362			schemaVersion: WITNESS_REACT_BOILERPLATE_ZERO_SW_SCHEMA,
363			result: 'pass',
364			fixture: REACT_BOILERPLATE_ZERO_SW_FIXTURE,
365			source,
366			provenance,
367			canonicalReceipt: {
368				path: relative(root, fixtureReceiptPath),
369				canonicalDigest: canonicalReceipt.integrity.canonicalDigest,
370				sha256: sha256(canonicalBytes),
371			},
372			supersedes: {
373				...REACT_BOILERPLATE_ZERO_SW_SUPERSEDES.witness,
374				scope: 'current-zero-service-worker-policy-only',
375				originalOfflineFirstEvidenceRetained: true,
376			},
377			runs,
378			mutations,
379			zeroServiceWorker: zeroObservation,
380			readiness: {
381				reactLineage: { ready: 1, total: 4, counted: true },
382				alignedReact: { ready: 0, total: 4, counted: false },
383				overall: { ready: 3, total: 12 },
384			},
385			locality: { mode: 'offline', successfulNonLoopback: 0, osWideIsolation: false },
386			nonclaims: [
387				'This is one already-counted React lineage and does not establish generic React support or advance readiness before Judge audit.',
388				'T060 original offline-first behavior remains valid; this receipt supersedes it only for current zero-service-worker policy.',
389				'Drag remains not-tested because the application has no genuine drag surface.',
390				'Locality is process-scoped and does not establish OS-wide isolation.',
391				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
392			],
393			integrity: { algorithm: 'sha256', canonicalDigest: '' },
394		};
395		receipt.integrity.canonicalDigest = witnessReactBoilerplateZeroSwDigest(receipt);
396		parseWitnessReactBoilerplateZeroSwReceipt(receipt);
397		await mkdir(witnessEvidence, { recursive: true });
398		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonicalize(receipt)}\n`, {
399			flag: 'wx',
400		});
401		await writeFile(
402			join(witnessEvidence, 'receipt.md'),
403			renderWitnessReactBoilerplateZeroSwReceipt(receipt),
404			{ flag: 'wx' },
405		);
406		await appendAggregate(receipt, canonicalReceipt);
407		await protectedHashes();
408		return receipt;
409	}
410	
411	export async function verifyWitnessReactBoilerplateZeroSw(
412		output = witnessEvidence,
413	): Promise<WitnessReactBoilerplateZeroSwReceipt> {
414		await protectedHashes();
415		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
416		const receipt = parseWitnessReactBoilerplateZeroSwReceipt(
417			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
418		);
419		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
420			throw new Error('React Boilerplate zero-SW linked Witness provenance differs');
421		const canonicalBytes = await readFile(join(root, receipt.canonicalReceipt.path));
422		if (sha256(canonicalBytes) !== receipt.canonicalReceipt.sha256)
423			throw new Error('React Boilerplate zero-SW canonical receipt bytes drifted');
424		parseReactBoilerplateZeroSwReceipt(JSON.parse(canonicalBytes.toString('utf8')));
425		if (
426			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
427			renderWitnessReactBoilerplateZeroSwReceipt(receipt)
428		)
429			throw new Error('React Boilerplate zero-SW human Witness receipt differs');
430		const serialized = canonicalize(receipt);
431		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
432			throw new Error('React Boilerplate zero-SW receipt leaks host identity');
433		return receipt;
434	}
435	
436	export async function main(args = process.argv.slice(2)): Promise<void> {
437		const publishIndex = args.indexOf('--publish');
438		const verifyIndex = args.indexOf('--verify');
439		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
440			const output = resolve(root, args[publishIndex + 1]!);
441			if (output !== witnessEvidence)
442				throw new Error('React Boilerplate zero-SW publish path differs');
443			const receipt = await runWitnessReactBoilerplateZeroSw();
444			process.stdout.write(
445				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
446			);
447			return;
448		}
449		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
450			const receipt = await verifyWitnessReactBoilerplateZeroSw(
451				resolve(root, args[verifyIndex + 1]!),
452			);
453			process.stdout.write(
454				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
455			);
456			return;
457		}
458		throw new Error(
459			'React Boilerplate zero-SW Witness runner requires --run-twice --publish <dir> or --verify <dir>',
460		);
461	}
462	
463	if (basename(process.argv[1] ?? '') === 'react-boilerplate-zero-sw-run.ts')
464		main().catch((error: unknown) => {
465			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
466			process.exitCode = 1;
467		});
