334				allowNetwork: args.includes('--allow-network'),
335				consentId: valueAfter('--consent-id'),
336			});
337			console.log(
338				JSON.stringify({
339					result: 'ingested',
340					purpose: result.purpose,
341					consentId: result.consent.consentId,
342					packages: result.packages.length,
343				}),
344			);
345		} else if (command === 'trust:generate') {
346			const policyPath = valueAfter('--policy');
347			const outputDir = valueAfter('--output');
348			if (!policyPath || !outputDir)
349				throw new Error('trust:generate requires --policy and --output');
350			console.log(
351				JSON.stringify(
352					await generateTrustPackage({
353						offline: args.includes('--offline'),
354						policyPath,
355						outputDir,
356					}),
357				),
358			);
359		} else if (command === 'trust:verify') {
360			const outputDir = args.find((arg) => !arg.startsWith('--'));
361			console.log(
362				JSON.stringify(
