364						outputDir: outputDir ?? 'evidence/trust/current',
365						compareDir: valueAfter('--compare'),
366						environment: args.includes('--offline')
367							? { ...process.env, VERSIONLESS_NETWORK_MODE: 'offline' }
368							: process.env,
369					}),
370				),
371			);
372		} else throw new Error(`Unknown command: ${command}`);
373	} catch (error) {
374		console.error(error instanceof Error ? error.stack : String(error));
375		process.exitCode = 1;
376	}
