import React from 'react';
import {Box, Flex} from 'theme-ui';
import dayjs from 'dayjs';
import utc from 'dayjs/plugin/utc';
import {colors, Badge, Text} from '../common';
import {SmileTwoTone, StarFilled} from '../icons';
import {formatRelativeTime} from '../../utils';

dayjs.extend(utc);

// TODO: add types!
const formatConversation = (conversation: any, messages: Array<any> = []) => {
  const recent = messages[messages.length - 1];
  const ts = recent ? recent.created_at : conversation.created_at;
  const created = dayjs.utc(ts);
  const date = formatRelativeTime(created);

  return {
    ...conversation,
    date: date || '1d', // TODO
    preview: recent && recent.body ? recent.body : '...',
    messages: messages,
  };
};

const ConversationItem = ({
  conversation,
  messages,
  color,
  isHighlighted,
  onSelectConversation,
}: {
  conversation: Array<any>;
  messages: Array<any>;
  color: string;
  isHighlighted?: boolean;
  onSelectConversation: (id: string) => void;
}) => {
  const formatted = formatConversation(conversation, messages);
  const {id, priority, status, customer, date, preview, read} = formatted;
  const {name, email} = customer;
  const isPriority = priority === 'priority';
  const isClosed = status === 'closed';

  return (
    <Box
      p={3}
      sx={{
        opacity: isClosed ? 0.8 : 1,
        borderBottom: '1px solid #f0f0f0',
        borderLeft: isHighlighted ? `2px solid ${colors.primary}` : null,
        background: isHighlighted ? colors.blue[0] : null,
        cursor: 'pointer',
      }}
      onClick={() => onSelectConversation(id)}
    >
      <Flex mb={2} sx={{justifyContent: 'space-between'}}>
        <Flex sx={{alignItems: 'center'}}>
          <Box mr={2}>
            {isPriority ? (
              <StarFilled style={{fontSize: 16, color: colors.gold}} />
            ) : (
              <SmileTwoTone style={{fontSize: 16}} twoToneColor={color} />
            )}
          </Box>
          <Text strong>{name || email || 'Anonymous User'}</Text>
        </Flex>

        {read ? (
          <Text type="secondary">{date}</Text>
        ) : (
          <Badge status="processing" />
        )}
      </Flex>
      <Box
        style={{
          whiteSpace: 'nowrap',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
        }}
      >
        {read ? (
          <Text type="secondary">{preview}</Text>
        ) : (
          <Text strong>{preview}</Text>
        )}
      </Box>
    </Box>
  );
};

export default ConversationItem;
import React from 'react';
import {Box, Flex} from 'theme-ui';
import dayjs from 'dayjs';
import utc from 'dayjs/plugin/utc';
import {colors, Text, Tooltip} from '../common';
import {UserOutlined} from '../icons';
import {formatRelativeTime} from '../../utils';
import {Message} from '../../types';

dayjs.extend(utc);

type Props = {
  message: Message;
  isMe?: boolean;
  isLastInGroup?: boolean;
  shouldDisplayTimestamp?: boolean;
};

const ChatMessage = ({
  message,
  isMe,
  isLastInGroup,
  shouldDisplayTimestamp,
}: Props) => {
  const {body, created_at, user} = message;
  const isAgent = !!user;
  // TODO: once we have customer metadata, show customer name/email here instead
  const tooltip = user ? user.email : 'Anonymous Customer';
  const created = dayjs.utc(created_at);
  const timestamp = formatRelativeTime(created);

  if (isMe) {
    return (
      <Box pr={0} pl={4} pb={isLastInGroup ? 3 : 2}>
        <Flex sx={{justifyContent: 'flex-end'}}>
          <Box
            px={3}
            py={2}
            sx={{
              color: colors.white,
              background: colors.primary,
              borderRadius: 4,
            }}
          >
            {body}
          </Box>
        </Flex>
        {shouldDisplayTimestamp && (
          <Flex m={1} sx={{justifyContent: 'flex-end'}}>
            <Text type="secondary">Sent {timestamp}</Text>
          </Flex>
        )}
      </Box>
    );
  }

  return (
    <Box pr={4} pl={0} pb={isLastInGroup ? 3 : 2}>
      <Flex sx={{justifyContent: 'flex-start', alignItems: 'center'}}>
        <Tooltip title={tooltip}>
          <Flex
            mr={2}
            sx={{
              bg: isAgent ? colors.primary : colors.gold,
              height: 32,
              width: 32,
              borderRadius: '50%',
              justifyContent: 'center',
              alignItems: 'center',
              color: '#fff',
            }}
          >
            {isAgent ? (
              tooltip.slice(0, 1).toUpperCase()
            ) : (
              <UserOutlined style={{color: colors.white}} />
            )}
          </Flex>
        </Tooltip>

        <Box
          px={3}
          py={2}
          sx={{
            color: colors.black,
            background: 'rgb(245, 245, 245)',
            borderRadius: 4,
            maxWidth: '80%',
          }}
        >
          {body}
        </Box>
      </Flex>
      {shouldDisplayTimestamp && (
        <Flex my={1} mx={2} pl={4} sx={{justifyContent: 'flex-start'}}>
          <Text type="secondary">Sent {timestamp}</Text>
        </Flex>
      )}
    </Box>
  );
};

export default ChatMessage;

