23	export type ServiceWorkerTelemetry = {
24		state: 'ready' | 'timeout';
25		registration: {
26			scriptPath: string | null;
27			scope: string | null;
28			installing: string | null;
29			waiting: string | null;
30			active: string | null;
31		};
32		controller: string | null;
33		cacheNames: string[];
34		cacheEntries: Array<{ name: string; paths: string[] }>;
35		workerEvents: Array<
36			| { kind: 'registration'; scopePath: string }
37			| { kind: 'version'; scriptPath: string; status: string; runningStatus: string }
38			| {
39					kind: 'error';
40					message: string;
41					sourcePath: string;
42					lineNumber: number;
43					columnNumber: number;
44			  }
45		>;
46	};
