48	export type WitnessTransportRequest = {
49		protocol: string;
50		host: string;
51		pathname: string;
52		search: string;
53		method: string;
54		resourceType: string;
55	};
56	
57	export type WitnessTransportDecision =
58		| { action: 'continue' }
59		| { action: 'fulfill'; status: number; contentType: string; body: Buffer };
60	
61	export type ServiceWorkerObserverFinalization = {
62		state: 'target-closed';
63		detach: 'owned-detach-complete';
64		pageClose: 'owned-page-close-complete';
65		workerEvents: ServiceWorkerTelemetry['workerEvents'];
66	};
67	
68	export type WitnessDifferentialEvent = {
69		sequence: number;
70		timestampMs: number;
71		source: 'browser' | 'context-route' | 'manifest' | 'static-server' | 'worker' | 'teardown';
72		phase: string;
73		urlPath: string | null;
74		detail: Record<string, boolean | number | string | null>;
75	};
76	
77	export type PlaywrightWitnessHost = {
78		browser: WitnessBrowser;
79		locality(): { successfulNonLoopback: 0; mockedNonLoopback: number };
80		serviceWorkerTelemetry(timeoutMs: number): Promise<ServiceWorkerTelemetry>;
81		serviceWorkerObserverFinalization(): ServiceWorkerObserverFinalization;
82	};
83	
84	const MAX_TELEMETRY_TIMEOUT_MS = 15_000;
85	const MAX_TRANSPORT_BODY_BYTES = 1_048_576;
86	
87	export function validateWitnessTransportDecision(
88		decision: WitnessTransportDecision,
89	): WitnessTransportDecision {
90		if (decision.action === 'continue') return decision;
91		if (
92			!Number.isInteger(decision.status) ||
93			decision.status < 200 ||
94			decision.status > 599 ||
95			decision.contentType.length === 0 ||
96			decision.contentType.length > 128 ||
97			decision.body.length > MAX_TRANSPORT_BODY_BYTES
98		)
99			throw new Error('Witness transport fulfillment exceeds its fixed boundary');
100		return decision;
101	}
102	
103	export function validateWitnessQualificationTypingMode(options: {
104		clear: boolean;
105		keyEvents: boolean;
106	}): void {
107		if (options.clear || !options.keyEvents)
108			throw new Error('Witness qualification host rejects fill-backed typing modes');
109	}
110	
111	function boundedTelemetryTimeout(timeoutMs: number): number {
112		if (!Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > MAX_TELEMETRY_TIMEOUT_MS)
113			throw new Error('Witness service-worker telemetry timeout is outside its fixed boundary');
114		return timeoutMs;
115	}
