117	async function observeServiceWorkers(
118		cdp: CDPSession,
119		page: Page,
120		workerEvents: ServiceWorkerTelemetry['workerEvents'],
121		diagnosticEvent?: (event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>) => void,
122	): Promise<{
123		finalize(): Promise<void>;
124		readback(): ServiceWorkerObserverFinalization | null;
125	}> {
126		let state: 'attached' | 'finalizing' | 'detached' | 'target-closed' = 'attached';
127		const observerState = (): typeof state => state;
128		let finalization: ServiceWorkerObserverFinalization | null = null;
129		const onRegistrationUpdated = (event: unknown): void => {
130			const registrations = (event as { registrations?: Array<{ scopeURL?: string }> })
131				.registrations;
132			for (const registration of registrations ?? []) {
133				diagnosticEvent?.({
134					source: 'worker',
135					phase: 'registration',
136					urlPath: parseURL(registration.scopeURL ?? '').pathname || '',
137					detail: {},
138				});
139				workerEvents.push({
140					kind: 'registration',
141					scopePath: parseURL(registration.scopeURL ?? '').pathname || '',
142				});
143			}
144		};
145		const onVersionUpdated = (event: unknown): void => {
146			const versions = (
147				event as {
148					versions?: Array<{
149						scriptURL?: string;
150						status?: string;
151						runningStatus?: string;
152					}>;
153				}
154			).versions;
155			for (const version of versions ?? []) {
156				diagnosticEvent?.({
157					source: 'worker',
158					phase: 'version',
159					urlPath: parseURL(version.scriptURL ?? '').pathname || '',
160					detail: {
161						status: version.status ?? 'unknown',
162						runningStatus: version.runningStatus ?? 'unknown',
163					},
164				});
165				workerEvents.push({
166					kind: 'version',
167					scriptPath: parseURL(version.scriptURL ?? '').pathname || '',
168					status: version.status ?? 'unknown',
169					runningStatus: version.runningStatus ?? 'unknown',
170				});
171			}
172		};
173		const onWorkerError = (event: unknown): void => {
174			const nested = (event as { errorMessage?: unknown }).errorMessage;
175			const report =
176				nested !== null && typeof nested === 'object'
177					? (nested as Record<string, unknown>)
178					: (event as Record<string, unknown>);
179			workerEvents.push({
180				kind: 'error',
181				message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
182				sourcePath:
183					typeof report.sourceURL === 'string'
184						? parseURL(report.sourceURL).pathname || ''
185						: '',
186				lineNumber: typeof report.lineNumber === 'number' ? report.lineNumber : 0,
187				columnNumber: typeof report.columnNumber === 'number' ? report.columnNumber : 0,
188			});
189			diagnosticEvent?.({
190				source: 'worker',
191				phase: 'error',
192				urlPath:
193					typeof report.sourceURL === 'string'
194						? parseURL(report.sourceURL).pathname || ''
195						: '',
196				detail: {
197					message: typeof report.errorMessage === 'string' ? report.errorMessage : 'unknown',
198				},
199			});
200		};
201		const onTargetClosed = (): void => {
202			if (state !== 'detached')
203				throw new Error(`Witness service-worker observer target closed while ${state}`);
204			state = 'target-closed';
205		};
206		cdp.on('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
207		cdp.on('ServiceWorker.workerVersionUpdated', onVersionUpdated);
208		cdp.on('ServiceWorker.workerErrorReported', onWorkerError);
209		page.on('close', onTargetClosed);
210		await cdp.send('ServiceWorker.enable');
211		return {
212			finalize: async () => {
213				if (state !== 'attached')
214					throw new Error(`Witness service-worker observer duplicate finalization: ${state}`);
215				if (page.isClosed())
216					throw new Error(
217						'Witness service-worker observer target closed before finalization',
218					);
219				state = 'finalizing';
220				diagnosticEvent?.({ source: 'teardown', phase: 'freeze', urlPath: null, detail: {} });
221				const snapshot = Object.freeze(
222					structuredClone(workerEvents).sort((left, right) =>
223						JSON.stringify(left).localeCompare(JSON.stringify(right)),
224					),
225				);
226				cdp.off('ServiceWorker.workerRegistrationUpdated', onRegistrationUpdated);
227				cdp.off('ServiceWorker.workerVersionUpdated', onVersionUpdated);
228				cdp.off('ServiceWorker.workerErrorReported', onWorkerError);
229				await cdp.detach();
230				state = 'detached';
231				diagnosticEvent?.({ source: 'teardown', phase: 'detached', urlPath: null, detail: {} });
232				await page.close();
233				page.off('close', onTargetClosed);
234				if (observerState() !== 'target-closed')
235					throw new Error('Witness service-worker observer missed the owned page close');
236				finalization = {
237					state: 'target-closed',
238					detach: 'owned-detach-complete',
239					pageClose: 'owned-page-close-complete',
240					workerEvents: [...snapshot],
241				};
242				diagnosticEvent?.({
243					source: 'teardown',
244					phase: 'target-closed',
245					urlPath: null,
246					detail: {},
247				});
248			},
249			readback: () => (finalization === null ? null : structuredClone(finalization)),
250		};
251	}
252	
253	function loopback(url: string): boolean {
254		const hostname = parseHost(parseURL(url).host ?? '').hostname;
255		return hostname === '127.0.0.1' || hostname === 'localhost' || hostname === '::1';
256	}
257	
258	function modifiers(mask: number): string[] {
259		return [
260			...(mask & 1 ? ['Alt'] : []),
261			...(mask & 2 ? ['Control'] : []),
262			...(mask & 4 ? ['Meta'] : []),
263			...(mask & 8 ? ['Shift'] : []),
264		];
265	}
266	
267	function keyWithModifiers(key: string, mask: number): string {
268		return [...modifiers(mask), key].join('+');
269	}
270	
271	async function requestRecord(request: Request, startedAt: number): Promise<BrowserNetworkRequest> {
272		const response = await request.response();
273		return {
274			url: request.url(),
275			method: request.method(),
276			resourceType: request.resourceType(),
277			startTimeMs: startedAt,
278			responseTimeMs: response === null ? null : Date.now(),
279			endTimeMs: Date.now(),
280			durationMs: Date.now() - startedAt,
281			status: response?.status() ?? null,
282			mimeType: response?.headers()['content-type'] ?? null,
283			encodedDataLength: null,
284			failedReason: request.failure()?.errorText ?? null,
285			initiatorType: null,
286		};
287	}
