289	async function waitForScrollableChange(
290		page: Page,
291		target: string | null,
292		deltaX: number,
293		deltaY: number,
294		timeoutMs: number,
295	): Promise<void> {
296		const expression =
297			target === null
298				? '({ x: window.scrollX, y: window.scrollY })'
299				: `(() => { const element = document.querySelector(${JSON.stringify(target)}); return element === null ? null : { x: element.scrollLeft, y: element.scrollTop }; })()`;
300		const before = (await page.evaluate(expression)) as { x: number; y: number } | null;
301		if (target !== null) await page.locator(target).first().hover({ timeout: timeoutMs });
302		await page.mouse.wheel(deltaX, deltaY);
303		await page.waitForFunction(
304			({ stateExpression, previous }) => {
305				const current = globalThis.eval(stateExpression) as { x: number; y: number } | null;
306				return (
307					current !== null &&
308					(previous === null || current.x !== previous.x || current.y !== previous.y)
309				);
310			},
311			{ stateExpression: expression, previous: before },
312			{ timeout: timeoutMs },
313		);
314	}
