316	function adaptPage(
317		page: Page,
318		closePage: () => Promise<void>,
319		navigationWaitUntil: 'domcontentloaded' | 'networkidle',
320	): WitnessBrowserPage {
321		const consoleListeners: Array<(message: BrowserConsoleMessage) => void> = [];
322		const pageErrorListeners: Array<(error: BrowserPageError) => void> = [];
323		const failureListeners: Array<(failure: BrowserRequestFailure) => void> = [];
324		const requestListeners: Array<(request: BrowserNetworkRequest) => void> = [];
325		const navigationListeners: Array<(url: string) => void> = [];
326		const requestStarts = new WeakMap<Request, number>();
327		page.on('console', (message) => {
328			for (const listener of consoleListeners)
329				listener({ level: message.type(), text: message.text() });
330		});
331		page.on('pageerror', (error) => {
332			for (const listener of pageErrorListeners) listener({ message: error.message });
333		});
334		page.on('request', (request) => requestStarts.set(request, Date.now()));
335		page.on('requestfailed', (request) => {
336			const failure = {
337				url: request.url(),
338				method: request.method(),
339				reason: request.failure()?.errorText ?? null,
340			};
341			for (const listener of failureListeners) listener(failure);
342			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
343				for (const listener of requestListeners) listener(record);
344			});
345		});
346		page.on('requestfinished', (request) => {
347			void requestRecord(request, requestStarts.get(request) ?? Date.now()).then((record) => {
348				for (const listener of requestListeners) listener(record);
349			});
350		});
351		page.on('framenavigated', (frame) => {
352			if (frame === page.mainFrame())
353				for (const listener of navigationListeners) listener(frame.url());
354		});
355		return {
356			goto: async (url) => void (await page.goto(url, { waitUntil: navigationWaitUntil })),
357			reload: async () => void (await page.reload({ waitUntil: navigationWaitUntil })),
358			content: () => page.content(),
359			screenshot: async (filePath) => void (await page.screenshot({ path: filePath })),
360			evaluate: (expression) => page.evaluate(expression),
361			waitForExpression: async (expression, timeoutMs) =>
362				void (await page.waitForFunction(expression, undefined, { timeout: timeoutMs })),
363			click: async (selector, timeoutMs) =>
364				void (await page.locator(selector).first().click({ timeout: timeoutMs })),
365			type: async (selector, text, options, timeoutMs) => {
366				const locator = page.locator(selector).first();
367				const type = await locator.getAttribute('type');
368				validateWitnessQualificationTypingMode(options);
369				for (const character of text) await locator.press(character, { timeout: timeoutMs });
370				return { passwordField: type === 'password' };
371			},
372			hover: async (selector, modifierMask, timeoutMs) =>
373				void (await page
374					.locator(selector)
375					.first()
376					.hover({
377						modifiers: modifiers(modifierMask) as Array<
378							'Alt' | 'Control' | 'Meta' | 'Shift'
379						>,
380						timeout: timeoutMs,
381					})),
382			press: async (selector, key, modifierMask, timeoutMs) =>
383				void (await page.locator(selector).first().press(keyWithModifiers(key, modifierMask), {
384					timeout: timeoutMs,
385				})),
386			drag: async () => {
387				throw new Error('drag is not-tested because no selected genuine surface exists');
388			},
389			scroll: async (target, deltaX, deltaY, _gesture, timeoutMs) =>
390				waitForScrollableChange(page, target, deltaX, deltaY, timeoutMs),
391			onConsoleMessage: (listener) => void consoleListeners.push(listener),
392			onPageError: (listener) => void pageErrorListeners.push(listener),
393			onRequestFailed: (listener) => void failureListeners.push(listener),
394			onNetworkRequest: (listener) => void requestListeners.push(listener),
395			emulateNetwork: async (conditions: BrowserNetworkConditions) =>
396				void (await page.context().setOffline(conditions.offline === true)),
397			clearNetworkEmulation: async () => void (await page.context().setOffline(false)),
398			onNavigated: (listener) => void navigationListeners.push(listener),
399			close: closePage,
400		};
401	}
