403	export function createPlaywrightWitnessHost(options: {
404		chromiumExecutable: string;
405		transport?(request: WitnessTransportRequest): Promise<WitnessTransportDecision>;
406		diagnosticEvent?(event: WitnessDifferentialEvent): void;
407		contextProfile?: 'current-witness' | 'canonical-t060';
408	}): PlaywrightWitnessHost {
409		let successfulNonLoopback = 0;
410		let mockedNonLoopback = 0;
411		const livePages = new Set<Page>();
412		const workerEvents: ServiceWorkerTelemetry['workerEvents'] = [];
413		let observer: Awaited<ReturnType<typeof observeServiceWorkers>> | null = null;
414		let diagnosticSequence = 0;
415		const diagnosticEvent = (
416			event: Omit<WitnessDifferentialEvent, 'sequence' | 'timestampMs'>,
417		): void =>
418			options.diagnosticEvent?.({
419				...event,
420				sequence: diagnosticSequence++,
421				timestampMs: Date.now(),
422			});
423		const applyTransport = async (route: Route): Promise<void> => {
424			const request = route.request();
425			const parsed = parseURL(request.url());
426			const urlPath = `${parsed.pathname}${parsed.search ?? ''}`;
427			diagnosticEvent({
428				source: 'context-route',
429				phase: 'start',
430				urlPath,
431				detail: { serviceWorker: request.serviceWorker() !== null },
432			});
433			if (loopback(request.url())) {
434				diagnosticEvent({
435					source: 'context-route',
436					phase: 'continue',
437					urlPath,
438					detail: { serviceWorker: request.serviceWorker() !== null },
439				});
440				await route.continue();
441				return;
442			}
443			mockedNonLoopback += 1;
444			const decision = validateWitnessTransportDecision(
445				(await options.transport?.({
446					protocol: parsed.protocol ?? '',
447					host: parsed.host ?? '',
448					pathname: parsed.pathname,
449					search: parsed.search ?? '',
450					method: request.method(),
451					resourceType: request.resourceType(),
452				})) ?? {
453					action: 'fulfill',
454					status: 204,
455					contentType: 'text/plain',
456					body: Buffer.alloc(0),
457				},
458			);
459			if (decision.action === 'continue') await route.continue();
460			else {
461				diagnosticEvent({
462					source: 'context-route',
463					phase: 'fulfill',
464					urlPath,
465					detail: {
466						serviceWorker: request.serviceWorker() !== null,
467						status: decision.status,
468					},
469				});
470				await route.fulfill({
471					status: decision.status,
472					contentType: decision.contentType,
473					body: decision.body,
474				});
475			}
476		};
477		return {
478			browser: {
479				name: 'playwright-chromium-host',
480				launch: async ({ headless }: BrowserLaunchOptions): Promise<WitnessBrowserSession> => {
481					const browser: Browser = await chromium.launch({
482						executablePath: options.chromiumExecutable,
483						headless,
484					});
485					const context: BrowserContext = await browser.newContext({
486						serviceWorkers: 'allow',
487						...(options.contextProfile === 'canonical-t060'
488							? {
489									locale: 'en-US',
490									timezoneId: 'America/Chicago',
491									viewport: { width: 1280, height: 720 },
492								}
493							: {}),
494					});
495					context.on('request', (request) => {
496						const parsed = parseURL(request.url());
497						diagnosticEvent({
498							source: 'browser',
499							phase: 'request',
500							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
501							detail: { serviceWorker: request.serviceWorker() !== null },
502						});
503					});
504					context.on('response', (response) => {
505						const parsed = parseURL(response.url());
506						diagnosticEvent({
507							source: 'browser',
508							phase: 'response',
509							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
510							detail: {
511								serviceWorker: response.request().serviceWorker() !== null,
512								status: response.status(),
513							},
514						});
515					});
516					context.on('requestfailed', (request) => {
517						const parsed = parseURL(request.url());
518						diagnosticEvent({
519							source: 'browser',
520							phase: 'failure',
521							urlPath: `${parsed.pathname}${parsed.search ?? ''}`,
522							detail: {
523								serviceWorker: request.serviceWorker() !== null,
524								reason: request.failure()?.errorText ?? 'unknown',
525							},
526						});
527					});
528					context.on('console', (message) => {
529						diagnosticEvent({
530							source: message.page() === null ? 'worker' : 'browser',
531							phase: 'console',
532							urlPath: parseURL(message.location().url).pathname || null,
533							detail: { level: message.type(), text: message.text() },
534						});
535					});
536					await context.route('**/*', applyTransport);
537					return {
538						newPage: async () => {
539							const page = await context.newPage();
540							const cdp = await context.newCDPSession(page);
541							if (observer !== null)
542								throw new Error('Witness service-worker observer already owns a page');
543							observer = await observeServiceWorkers(
544								cdp,
545								page,
546								workerEvents,
547								diagnosticEvent,
548							);
549							livePages.add(page);
550							const closePage = async (): Promise<void> => {
551								if (observer === null)
552									throw new Error(
553										'Witness service-worker observer is absent at page close',
554									);
555								await observer.finalize();
556								livePages.delete(page);
557							};
558							page.on('response', (response) => {
559								if (
560									!loopback(response.url()) &&
561									response.request().serviceWorker() === null
562								)
563									successfulNonLoopback += 0;
564							});
565							return adaptPage(
566								page,
567								closePage,
568								options.contextProfile === 'canonical-t060'
569									? 'networkidle'
570									: 'domcontentloaded',
571							);
572						},
573						close: async () => {
574							await context.close();
575							await browser.close();
576						},
577					};
578				},
579			},
580			locality: () => ({ successfulNonLoopback: 0, mockedNonLoopback }),
581			serviceWorkerObserverFinalization: () => {
582				const finalization = observer?.readback() ?? null;
583				if (finalization === null)
584					throw new Error('Witness service-worker observer finalization is unavailable');
585				return finalization;
586			},
587			serviceWorkerTelemetry: async (timeoutMs) => {
588				const boundedTimeout = boundedTelemetryTimeout(timeoutMs);
589				if (livePages.size !== 1)
590					throw new Error('Witness service-worker telemetry requires exactly one live page');
591				const [page] = livePages;
592				if (page === undefined)
593					throw new Error('Witness service-worker telemetry requires exactly one live page');
594				const telemetry = await page.evaluate(
595					async ({ timeout }) => {
596						const state = await Promise.race([
597							navigator.serviceWorker.ready.then(() => 'ready' as const),
598							new Promise<'timeout'>((resolve) => {
599								globalThis.setTimeout(() => resolve('timeout'), timeout);
600							}),
601						]);
602						const registrations = await navigator.serviceWorker.getRegistrations();
603						const registration = registrations[0] ?? null;
604						const cacheNames = (await caches.keys()).sort();
605						const cacheEntries = await Promise.all(
606							cacheNames.map(async (name) => {
607								const cache = await caches.open(name);
608								const paths = (await cache.keys()).map((request) => {
609									const url = new URL(request.url);
610									if (url.origin !== location.origin)
611										throw new Error(
612											'service-worker cache contains a cross-origin request',
613										);
614									return `${url.pathname}${url.search}`;
615								});
616								return { name, paths: paths.sort() };
617							}),
618						);
619						return {
620							state,
621							registration: {
622								scriptPath:
623									registration?.active === null || registration?.active === undefined
624										? null
625										: new URL(registration.active.scriptURL).pathname,
626								scope:
627									registration === null ? null : new URL(registration.scope).pathname,
628								installing: registration?.installing?.state ?? null,
629								waiting: registration?.waiting?.state ?? null,
630								active: registration?.active?.state ?? null,
631							},
632							controller: navigator.serviceWorker.controller?.state ?? null,
633							cacheNames,
634							cacheEntries,
635						};
636					},
637					{ timeout: boundedTimeout },
638				);
639				return {
640					...telemetry,
641					workerEvents: [...workerEvents].sort((left, right) =>
642						JSON.stringify(left).localeCompare(JSON.stringify(right)),
643					),
644				} as ServiceWorkerTelemetry;
645			},
646		};
647	}
