1	import { createHash } from 'node:crypto';
2	import { readFile, readdir } from 'node:fs/promises';
3	import * as path from 'pathe';
4	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
5	
6	/**
7	 * Fixture-scoped verification for the papercups create-react-app to Vite 8
8	 * build-stage lane. All application knowledge lives here; the reusable
9	 * capabilities it exercises live in @versionless/react and stay generic.
10	 */
11	
12	const root = path.resolve(import.meta.dirname, '../../../..');
13	const evidenceRoot = path.join(root, 'evidence/runs/react-papercups-v1-0-0');
14	const reactAdapterRoot = path.join(root, 'packages/frameworks/react/src');
15	
16	const sha256 = (value: string): string => createHash('sha256').update(value).digest('hex');
17	
18	export type BuildProfileLane = Readonly<{
19		digest: string;
20		files: ReadonlyArray<Readonly<{ path: string; sha256: string }>>;
21	}>;
22	export type BuildProfileBuild = Readonly<{
23		bundler: string;
24		runtime: string;
25		equal: boolean;
26		first: BuildProfileLane;
27		second: BuildProfileLane;
28	}>;
29	export type PapercupsBuildProfile = Readonly<{
30		schemaVersion: string;
31		result: string;
32		fixture: string;
33		builds: Readonly<{ baseline: BuildProfileBuild; target: BuildProfileBuild }>;
34		parity: Readonly<{ behavioral: string; journeys: string; runtimeEquivalence: string }>;
35		gates: Readonly<Record<string, string>>;
36		integrity: Readonly<{ algorithm: string; canonicalDigest: string }>;
37	}>;
38	
39	export type PapercupsBuildProfileVerification = Readonly<{
40		result: 'pass';
